/// <summary>
/// MPJ_14792_FreezeDefaultFinancialDimensions
/// Class <c>METLedgerJournalTransDailyFormDS_Extension</c> holds CoC functionalities regards DS
/// </summary>
[ExtensionOf(FormDataSourceStr(LedgerJournalTransDaily, LedgerJournalTrans))]
final class METLedgerJournalTransDailyFormDS_Extension
{
}

Method.Source:
/// <summary>
/// Write functionality CoC
/// </summary>
public void  write()
{
    next write();
    this.metUpdateDimensions();
}

    /// <summary>
    /// updates dimension after write. Write method contains update to dimensions.
    /// </summary>
    public void metUpdateDimensions()
    {
        FormDataSource      metDS                  = this;
        LedgerJournalTrans  metLedgerJournalTrans  = metDS.formRun().dataSource(formdataSourceStr(LedgerJournalTransVendPaym, LedgerJournalTrans)).cursor();
        LedgerJournalTable  metLedgerJournalTable  = LedgerJournalTable::find(metLedgerJournalTrans.JournalNum);
        LedgerJournalName   metLedgerJournalName   = LedgerJournalName::find(metLedgerJournalTable.journalname);

        if (metLedgerJournalName.METFreezeDefaultDimensions == NoYes::Yes && metLedgerJournalTrans.AccountType == LedgerJournalACType::Vend)
        {
            metLedgerjournaltrans.selectForUpdate(true);
            metLedgerjournaltrans.DefaultDimension = metLedgerJournalTable.DefaultDimension;
            metLedgerjournaltrans.update();
        }
        
    }
